UPDATE rule_run_nodes
SET node_kind = #{nodeKind},
    status = #{status},
    metrics_json = #{metricsJson,jdbcType=LONGVARCHAR},
    sample_uri = #{sampleUri,jdbcType=VARCHAR},
    error_message = #{errorMessage,jdbcType=VARCHAR},
    started_at = #{startedAt,jdbcType=TIMESTAMP,typeHandler=org.apache.ibatis.type.InstantTypeHandler},
    finished_at = #{finishedAt,jdbcType=TIMESTAMP,typeHandler=org.apache.ibatis.type.InstantTypeHandler}
WHERE id = #{id,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}
  AND run_id = #{runId,typeHandler=com.olist.datasets.typehandler.UuidTypeHandler}

